WITH filtered AS (SELECT *, CASE WHEN city = 'Singapore' THEN 1 ELSE 0 END AS is_singapore, TRIM(supplier_name) AS clean_supplier_name FROM suppliers WHERE city IS NOT NULL), metrics AS (SELECT id, supplier_name, city, rating, is_singapore, RANK() OVER (PARTITION BY country ORDER BY rating DESC) AS rating_rank, NTILE(10) OVER (PARTITION BY city, country ORDER BY rating DESC, id) AS rating_bucket FROM filtered), metrics_suppliers AS (SELECT *, LEAD(rating) OVER w_part AS next_rating, LAG(rating) OVER w_part AS prev_rating, LEAD(rating_bucket) OVER w_part AS next_rating_bucket, ROW_NUMBER() OVER w_part AS seq_no, FIRST_VALUE(rating_rank) IGNORE NULLS OVER w_ordered AS first_known_rating_rank FROM metrics WINDOW w_part AS (PARTITION BY city ORDER BY is_singapore, id), w_ordered AS (PARTITION BY city ORDER BY rating_rank, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), filtered_suppliers AS (SELECT id, supplier_name, city, rating, is_singapore, rating_rank, rating_bucket, prev_rating, next_rating_bucket, seq_no, first_known_rating_rank, rating - first_known_rating_rank AS rating_minus_first_known_rating_rank, COALESCE(city, 'OTHER') AS city_filled FROM metrics_suppliers WHERE next_rating_bucket BETWEEN 5 AND 8) SELECT CASE WHEN first_known_rating_rank >= 9 THEN 'LARGE' ELSE 'SMALL' END AS first_known_rating_rank_tier, CASE WHEN rating_rank >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END AS rating_rank_tier, seq_no, COUNT(DISTINCT id) AS distinct_ids, APPROX_PERCENTILE(prev_rating, 0.95) AS prev_rating_p95, COUNT_IF(city = 'Chiang Mai') AS chiang_mai_events, COUNT(*) AS num_rows FROM filtered_suppliers GROUP BY CASE WHEN first_known_rating_rank >= 9 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN rating_rank >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END, seq_no HAVING prev_rating_p95 >= 0
